// customers-pricing · кейсы cp-03, cp-04 (.qa/tests/customers-pricing/) — жизненный цикл клиента.
// Создаёт только «QA-AUTO-customer-<ts>»; ссылку-приглашение НЕ отправляет и не копирует (регистрация = создание аккаунта).
// afterAll: удаляет клиента QA-AUTO этого прогона, если он остался.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, `../../../auth/${role}.json`);
test.use({ storageState: auth('admin') });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const C = `QA-AUTO-customer-${TS}`;
const ADDR = `QA-AUTO רחוב הבדיקה ${TS}, תל אביב`;

const rowOf = (page: Page, name: string) =>
  page.getByRole('button').filter({ hasText: name }).filter({ has: page.getByRole('button', { name: 'פעולות' }) }).first();

async function openList(page: Page) {
  await page.goto('/customers');
  await expect(page.getByRole('heading', { level: 1, name: 'לקוחות' })).toBeVisible();
  await expect(page.getByText(/^מציג \d+–\d+ מתוך \d+ תוצאות$/)).toBeVisible({ timeout: 20_000 });
}

async function menu(page: Page, name: string, item: string | RegExp) {
  await rowOf(page, name).getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: item }).click();
}

async function deleteCustomer(page: Page, name: string) {
  await openList(page);
  if (!(await rowOf(page, name).count())) return;
  await menu(page, name, /^מחיקה/);
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'מחיקת לקוח' })).toBeVisible();
  await dlg.getByRole('button', { name: /^מחיקה/ }).click();
  await expect(page.getByText(`"${name}" נמחק.`).or(page.getByText(new RegExp(`${name}.*נמחק\\.`))).first()).toBeVisible({ timeout: 15_000 });
  await expect(rowOf(page, name)).toHaveCount(0);
}

test.describe('customers — מחזור חיי לקוח (QA-AUTO)', () => {
  test.afterAll(async ({ browser }) => {
    const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL' });
    const page = await ctx.newPage();
    try {
      await deleteCustomer(page, C);
    } finally {
      await ctx.close();
    }
  });

  test('טופס לקוח חדש: שדה חובה, טלפון/אימייל/ח.פ., עד 15 ספרות, עד 50 תווים #6a70a5da #6a38cf5d @desktop', async ({ page }) => {
    await openList(page);
    await page.getByRole('button', { name: 'לקוח חדש' }).click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: 'לקוח חדש' })).toBeVisible();
    const submit = dlg.getByRole('button', { name: 'יצירת לקוח וקישור הזמנה' });
    const name = dlg.getByRole('textbox', { name: /^שם העסק/ });
    const phone = dlg.getByRole('textbox', { name: 'טלפון' });
    const email = dlg.getByRole('textbox', { name: 'אימייל' });
    const tax = dlg.getByRole('textbox', { name: 'ח.פ. / ת.ז.' });

    await submit.click();
    await expect(dlg.getByText('נא להזין שם עסק')).toBeVisible();
    await expect(name).toHaveAttribute('aria-invalid', 'true');

    await name.fill(`${C}-invalid`);
    await phone.fill('05a-123');
    await email.fill('bad');
    await tax.fill('12ab34');
    await submit.click();
    await expect(dlg.getByText('מספר טלפון יכול לכלול ספרות בלבד, עם + בתחילת המספר')).toBeVisible();
    await expect(dlg.getByText('כתובת אימייל לא תקינה')).toBeVisible();
    await expect(dlg.getByText('ח.פ. / ת.ז. יכול לכלול ספרות בלבד')).toBeVisible();
    await expect(dlg.getByRole('heading', { name: 'לקוח חדש' })).toBeVisible();

    await phone.fill('+1234567890123456');
    await email.fill('');
    await tax.fill('1234567890');
    await submit.click();
    await expect(dlg.getByText('מספר טלפון יכול לכלול עד 15 ספרות')).toBeVisible();

    await name.fill(`${C}-${'x'.repeat(60)}`);
    expect((await name.inputValue()).length).toBe(50);
    await expect(tax).toHaveAttribute('maxlength', '15');
    await expect(dlg.getByRole('textbox', { name: 'איש קשר' })).toHaveAttribute('maxlength', '50');

    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await openList(page);
    await expect(rowOf(page, `${C}-invalid`)).toHaveCount(0);
  });

  // Переключатель «יצירת קישור הצטרפות» не трогаем (по умолчанию вкл., #ea0fde) → ссылка создана, но не передана →
  // «ממתין להזמנה» остаётся верным и после #5a2dbd («ממתין להזמנה» — у клиента со ссылкой, ещё не зарегистрированного).
  test('יצירת לקוח עם קישור שלא נמסר — «ממתין להזמנה» #6a38cf5d #5a2dbd @desktop', async ({ page }) => {
    await openList(page);
    await page.getByRole('button', { name: 'לקוח חדש' }).click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('switch', { name: 'יצירת קישור הצטרפות' })).toHaveAttribute('aria-checked', 'true');
    await dlg.getByRole('textbox', { name: /^שם העסק/ }).fill(C);
    await dlg.getByRole('textbox', { name: 'איש קשר' }).fill('QA איש קשר');
    await dlg.getByRole('textbox', { name: 'טלפון' }).fill('0501234567');
    await dlg.getByRole('button', { name: 'יצירת לקוח וקישור הזמנה' }).click();
    await expect(page.getByText(`נוסף לרשימה. שלחו את קישור ההצטרפות.`).first()).toBeVisible({ timeout: 15_000 });
    await expect(dlg.getByRole('heading', { name: 'החשבון נפתח' })).toBeVisible();
    await expect(dlg.getByText('נוצר קישור הצטרפות אך הוא טרם נמסר ללקוח.')).toBeVisible();
    // Ссылку не отправляем и не копируем — только закрываем.
    await dlg.getByRole('button', { name: 'סגירה' }).click();
    await expect(rowOf(page, C)).toContainText('ממתין להזמנה');
    await expect(rowOf(page, C)).toContainText('0501234567');
  });

  test('עריכה: ולידציה, maxlength, כתובת נשמרת ומוצגת בכרטיס, מצב ריק הזמנות #6a70a5da #6a38cf5d @desktop', async ({ page }) => {
    await openList(page);
    test.skip(!(await rowOf(page, C).count()), 'клиент не создан');
    await menu(page, C, 'עריכה');
    await expect(page).toHaveURL(/\/customers\/[0-9a-f-]{36}\/edit$/);
    await expect(page.getByRole('heading', { level: 1, name: 'עריכת לקוח' })).toBeVisible();
    const main = page.getByRole('main');
    await expect(main.getByRole('textbox', { name: /^שם עסק/ })).toHaveAttribute('maxlength', '50');
    await expect(main.getByRole('textbox', { name: 'ח.פ. / ת.ז.' })).toHaveAttribute('maxlength', '15');
    await expect(main.getByRole('textbox', { name: 'שם איש קשר' })).toHaveAttribute('maxlength', '50');
    await expect(main.getByRole('textbox', { name: 'כתובת מלאה' })).toHaveAttribute('maxlength', '120');

    await expect(main.getByRole('textbox', { name: /^שם עסק/ })).toHaveValue(C);
    const phone = main.getByRole('textbox', { name: 'טלפון' });
    await phone.fill('abc');
    await main.getByRole('textbox', { name: 'כתובת מלאה' }).fill(ADDR);
    await page.getByRole('button', { name: 'שמירה', exact: true }).click();
    await expect(main.getByText('מספר טלפון יכול לכלול ספרות בלבד, עם + בתחילת המספר')).toBeVisible();
    await expect(page).toHaveURL(/\/edit$/);

    await phone.fill('0501234567');
    await page.getByRole('button', { name: 'שמירה', exact: true }).click();
    await expect(page.getByText(`עודכן.`).first()).toBeVisible({ timeout: 15_000 });
    await expect(page).toHaveURL(/\/customers$/);

    await rowOf(page, C).getByText(C, { exact: true }).click();
    await expect(page.getByRole('heading', { level: 1, name: C })).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText(ADDR)).toBeVisible();
    await expect(page.getByText('אין הזמנות עדיין.')).toBeVisible();
    await expect(page.getByRole('main').getByText("מס' הזמנות", { exact: true }).locator('xpath=following-sibling::*[1]')).toHaveText('0');
  });

  test('השבתה: «מושבת» ו«הפעלת לקוח» בתפריט #6a38cf5d @desktop', async ({ page }) => {
    await openList(page);
    test.skip(!(await rowOf(page, C).count()), 'клиент не создан');
    await menu(page, C, 'השבתת לקוח');
    await expect(rowOf(page, C)).toContainText('מושבת', { timeout: 15_000 });
    await rowOf(page, C).getByRole('button', { name: 'פעולות' }).click();
    await expect(page.getByRole('menuitem', { name: 'הפעלת לקוח' })).toBeVisible();
    await expect(page.getByRole('menuitem', { name: 'השבתת לקוח' })).toHaveCount(0);
    await page.keyboard.press('Escape');
  });

  test('מחיקת לקוח בלי הזמנות #6a38cf5d @desktop', async ({ page }) => {
    await openList(page);
    test.skip(!(await rowOf(page, C).count()), 'клиент не создан');
    await deleteCustomer(page, C);
  });

  test('לקוח מושבת לא יכול להתחבר / להזמין #6a38cf5d @desktop', async () => {
    test.skip(true, 'нужен аккаунт отключённого клиента (регистрация по ссылке = создание аккаунта)');
  });
});
